[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>WellStream Platform — Integrated Energy Data Management</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<link rel="stylesheet" href="shared.css">
<style>
/* ===== HOME PAGE STYLES ===== */
.hero {
  min-height: 100vh;
  background: linear-gradient(135deg, #0D1B2A 0%, #1B2838 40%, #0a1628 100%);
  display: flex;
  align-items: center;
  position: relative;
  overflow: hidden;
  padding-top: 80px;
}
.hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 70% 40%, rgba(0,180,216,0.12) 0%, transparent 60%),
              radial-gradient(ellipse at 20% 80%, rgba(108,194,74,0.08) 0%, transparent 50%);
}
.hero-grid {
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: linear-gradient(rgba(0,180,216,0.04) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(0,180,216,0.04) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: 0.5;
}
.hero-content {
  position: relative;
  z-index: 1;
  max-width: 760px;
}
.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(0,180,216,0.12);
  border: 1px solid rgba(0,180,216,0.3);
  color: #00B4D8;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding: 6px 16px;
  border-radius: 20px;
  margin-bottom: 28px;
}
.hero-eyebrow::before {
  content: '';
  width: 6px; height: 6px;
  background: #00B4D8;
  border-radius: 50%;
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.5; transform: scale(0.7); }
}
.hero h1 {
  font-size: clamp(2.2rem, 5vw, 3.8rem);
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.02em;
  color: #fff;
  margin-bottom: 24px;
  text-transform: uppercase;
}
.hero h1 span { color: #00B4D8; }
.hero-sub {
  font-size: 1.15rem;
  color: rgba(255,255,255,0.65);
  line-height: 1.7;
  max-width: 580px;
  margin-bottom: 40px;
}
.hero-ctas {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* Featured Product Banner */
.product-banner {
  background: linear-gradient(90deg, #15295A 0%, #1a3470 50%, #0D1B2A 100%);
  border-top: 1px solid rgba(0,180,216,0.2);
  border-bottom: 1px solid rgba(0,180,216,0.2);
  padding: 20px 0;
}
.product-banner-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
}
.product-banner-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #6CC24A;
}
.product-banner-name {
  font-size: 1.5rem;
  font-weight: 700;
  color: #fff;
}
.product-banner-tag {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.55);
  margin-top: 2px;
}

/* Use Cases */
.use-cases { background: #0D1B2A; }
.use-cases-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  background: rgba(0,180,216,0.1);
  border: 1px solid rgba(0,180,216,0.1);
  border-radius: 12px;
  overflow: hidden;
  margin-top: 48px;
}
.use-case-card {
  background: #111d2e;
  padding: 32px 28px;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
  position: relative;
}
.use-case-card::after {
  content: '';
  position: absolute;
  bottom: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, #00B4D8, #6CC24A);
  transform: scaleX(0);
  transition: transform 0.3s;
  transform-origin: left;
}
.use-case-card:hover { background: #162336; }
.use-case-card:hover::after { transform: scaleX(1); }
.use-case-icon {
  width: 44px; height: 44px;
  background: rgba(0,180,216,0.1);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 20px;
}
.use-case-card h3 {
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  margin-bottom: 8px;
  line-height: 1.3;
}
.use-case-card p {
  font-size: 0.82rem;
  color: rgba(255,255,255,0.45);
  line-height: 1.6;
}

/* Industry Tabs */
.industry-tabs-section { background: #111d2e; }
.tabs-nav {
  display: flex;
  gap: 0;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  margin-bottom: 40px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}
.tabs-nav::-webkit-scrollbar { height: 2px; }
.tabs-nav::-webkit-scrollbar-track { background: transparent; }
.tabs-nav::-webkit-scrollbar-thumb { background: rgba(0,180,216,0.3); }
.tab-btn {
  background: none;
  border: none;
  padding: 14px 24px;
  font-size: 0.88rem;
  font-weight: 500;
  color: rgba(255,255,255,0.45);
  cursor: pointer;
  white-space: nowrap;
  position: relative;
  transition: color 0.2s;
}
.tab-btn::after {
  content: '';
  position: absolute;
  bottom: -1px; left: 0; right: 0;
  height: 2px;
  background: #00B4D8;
  transform: scaleX(0);
  transition: transform 0.25s;
}
.tab-btn.active { color: #00B4D8; }
.tab-btn.active::after { transform: scaleX(1); }
.tab-btn:hover:not(.active) { color: rgba(255,255,255,0.75); }
.tab-pane { display: none; }
.tab-pane.active { display: grid; grid-template-columns: 1fr 1fr; gap: 40px; align-items: center; }
.tab-content-text h3 {
  font-size: 1.6rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 16px;
  line-height: 1.25;
}
.tab-content-text p {
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
  margin-bottom: 24px;
}
.tab-feature-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.tab-feature-list li {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  font-size: 0.88rem;
  color: rgba(255,255,255,0.65);
}
.tab-feature-list li::before {
  content: '✓';
  color: #6CC24A;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 1px;
}
.tab-visual {
  background: linear-gradient(135deg, #0D1B2A, #1B2838);
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: 12px;
  padding: 32px;
  min-height: 260px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  position: relative;
  overflow: hidden;
}
.tab-visual::before {
  content: '';
  position: absolute;
  top: -40px; right: -40px;
  width: 200px; height: 200px;
  background: radial-gradient(circle, rgba(0,180,216,0.12), transparent 70%);
  border-radius: 50%;
}
.tab-metric {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: 8px;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.tab-metric-label { font-size: 0.78rem; color: rgba(255,255,255,0.45); }
.tab-metric-value { font-size: 1.1rem; font-weight: 700; color: #00B4D8; }

/* Platform Ecosystem Diagram */
.ecosystem-section { background: #0D1B2A; }
.ecosystem-diagram {
  margin-top: 48px;
  display: grid;
  grid-template-columns: 1fr auto 1fr auto 1fr;
  align-items: center;
  gap: 0;
}
.eco-pillar {
  background: linear-gradient(135deg, #111d2e, #162336);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 16px;
  padding: 36px 28px;
  text-align: center;
  position: relative;
  overflow: hidden;
  transition: border-color 0.3s, transform 0.3s;
}
.eco-pillar:hover {
  border-color: rgba(0,180,216,0.5);
  transform: translateY(-4px);
}
.eco-pillar::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: linear-gradient(90deg, #00B4D8, #6CC24A);
}
.eco-icon {
  font-size: 2.5rem;
  margin-bottom: 16px;
  display: block;
}
.eco-pillar h3 {
  font-size: 1.05rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 12px;
}
.eco-pillar p {
  font-size: 0.82rem;
  color: rgba(255,255,255,0.5);
  line-height: 1.6;
}
.eco-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 12px;
}
.eco-connector-line {
  width: 40px;
  height: 2px;
  background: linear-gradient(90deg, #00B4D8, rgba(0,180,216,0.3));
  position: relative;
}
.eco-connector-line::after {
  content: '';
  position: absolute;
  right: -6px; top: -4px;
  border: 5px solid transparent;
  border-left-color: rgba(0,180,216,0.5);
}
.eco-center-badge {
  position: absolute;
  bottom: -1px;
  left: 50%;
  transform: translateX(-50%);
  background: #6CC24A;
  color: #0D1B2A;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 6px 6px 0 0;
}

/* Company Culture */
.culture-section {
  background: linear-gradient(135deg, #15295A, #1B2838);
  position: relative;
  overflow: hidden;
}
.culture-section::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 80% 50%, rgba(108,194,74,0.08), transparent 60%);
}
.culture-inner {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.culture-stats {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.culture-stat {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 12px;
  padding: 24px;
  text-align: center;
}
.culture-stat-num {
  font-size: 2rem;
  font-weight: 800;
  color: #6CC24A;
  display: block;
}
.culture-stat-label {
  font-size: 0.78rem;
  color: rgba(255,255,255,0.5);
  margin-top: 4px;
}

/* Renewables CTA */
.renewables-section {
  background: linear-gradient(135deg, #0a1f0a, #0D1B2A);
  border-top: 1px solid rgba(108,194,74,0.2);
  text-align: center;
}
.renewables-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: rgba(108,194,74,0.1);
  border: 1px solid rgba(108,194,74,0.3);
  color: #6CC24A;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding: 6px 16px;
  border-radius: 20px;
  margin-bottom: 24px;
}
.renewables-section h2 {
  font-size: 2.2rem;
  font-weight: 800;
  color: #fff;
  margin-bottom: 16px;
}
.renewables-section p {
  max-width: 580px;
  margin: 0 auto 36px;
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  background: #1B2838;
  border-top: 1px solid rgba(0,180,216,0.2);
  padding: 20px 24px;
  z-index: 1000;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  transform: translateY(100%);
  transition: transform 0.4s ease;
}
.cookie-banner.visible { transform: translateY(0); }
.cookie-text {
  font-size: 0.85rem;
  color: rgba(255,255,255,0.65);
  line-height: 1.5;
}
.cookie-text a { color: #00B4D8; text-decoration: none; }
.cookie-actions { display: flex; gap: 12px; flex-shrink: 0; }

@media (max-width: 768px) {
  .use-cases-grid { grid-template-columns: 1fr 1fr; }
  .tab-pane.active { grid-template-columns: 1fr; }
  .tab-visual { display: none; }
  .ecosystem-diagram { grid-template-columns: 1fr; grid-template-rows: auto; gap: 16px; }
  .eco-connector { transform: rotate(90deg); padding: 4px 0; }
  .eco-connector-line { width: 30px; }
  .culture-inner { grid-template-columns: 1fr; gap: 32px; }
  .cookie-banner { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 480px) {
  .use-cases-grid { grid-template-columns: 1fr; }
}
</style>
</head>
<body>

<!-- NAV -->
<nav class="navbar" id="navbar">
  <div class="container nav-inner">
    <a href="index.html" class="nav-logo">
      <span class="logo-ws">Well</span><span class="logo-stream">Stream</span>
    </a>
    <button class="nav-toggle" id="navToggle" aria-label="Menu">
      <span></span><span></span><span></span>
    </button>
    <div class="nav-links" id="navLinks">
      <div class="nav-dropdown">
        <button class="nav-link dropdown-toggle">Platform <span class="caret">▾</span></button>
        <div class="dropdown-menu">
          <a href="platform-overview.html" class="dropdown-item">
            <span class="di-icon">⬡</span>
            <span><strong>Platform Overview</strong><br><small>Core capabilities & features</small></span>
          </a>
          <a href="security.html" class="dropdown-item">
            <span class="di-icon">🔒</span>
            <span><strong>Security</strong><br><small>SOC compliance & infrastructure</small></span>
          </a>
          <a href="integration.html" class="dropdown-item">
            <span class="di-icon">⚡</span>
            <span><strong>Integration</strong><br><small>ETL, APIs & dashboards</small></span>
          </a>
        </div>
      </div>
      <a href="index.html#use-cases" class="nav-link">Solutions</a>
      <a href="index.html#culture" class="nav-link">Company</a>
    </div>
    <a href="request-demo.html" class="btn btn-primary nav-cta">Request A Demo</a>
  </div>
</nav>

<!-- HERO -->
<section class="hero">
  <div class="hero-grid"></div>
  <div class="container">
    <div class="hero-content">
      <div class="hero-eyebrow">Energy Data Management Platform</div>
      <h1>Get Real-Time Data Across Your <span>Entire Operation</span></h1>
      <p class="hero-sub">The integrated energy data platform built for operators who demand speed, security, and visibility across the well data lifecycle.</p>
      <div class="hero-ctas">
        <a href="platform-overview.html" class="btn btn-primary">Explore the Platform</a>
        <a href="request-demo.html" class="btn btn-outline">Request A Demo</a>
      </div>
    </div>
  </div>
</section>

<!-- FEATURED PRODUCT BANNER -->
<div class="product-banner">
  <div class="container product-banner-inner">
    <div>
      <div class="product-banner-label">Featured Product</div>
      <div class="product-banner-name">WellStream Innova</div>
      <div class="product-banner-tag">Real-Time Directional Data Exchange</div>
    </div>
    <a href="request-demo.html" class="btn btn-sm btn-outline">Learn More</a>
  </div>
</div>

<!-- USE CASES -->
<section class="use-cases section" id="use-cases">
  <div class="container">
    <div class="section-label">Use Cases</div>
    <h2 class="section-title">See the WellStream Platform<br>in Action</h2>
    <p class="section-desc">From drilling to production, land to water, watch how WellStream transforms every phase of your operations. Streamline workflows, unlock real-time insights, and make every decision count.</p>
    <div class="use-cases-grid">
      <div class="use-case-card">
        <div class="use-case-icon">⛏</div>
        <h3>Drilling &amp; Completions Management</h3>
        <p>Centralize drilling programs, daily reports, and well design data in one accessible hub.</p>
      </div>
      <div class="use-case-card">
        <div class="use-case-icon">📊</div>
        <h3>Production Operations Oversight</h3>
        <p>Monitor production volumes, allocations, and decline curves with real-time dashboards.</p>
      </div>
      <div class="use-case-card">
        <div class="use-case-icon">🛡</div>
        <h3>Asset Integrity Monitoring</h3>
        <p>Track well integrity risks, inspection schedules, and compliance status across your portfolio.</p>
      </div>
      <div class="use-case-card">
        <div class="use-case-icon">💧</div>
        <h3>Hydraulic Frac Data Centralization</h3>
        <p>Consolidate frac stage data, chemical usage, and pressure readings for every completion.</p>
      </div>
      <div class="use-case-card">
        <div class="use-case-icon">🏗</div>
        <h3>Facility Construction &amp; Commissioning</h3>
        <p>Manage site activity, construction milestones, and commissioning workflows digitally.</p>
      </div>
      <div class="use-case-card">
        <div class="use-case-icon">🗺</div>
        <h3>Geospatial Asset Analysis</h3>
        <p>Visualize well locations, land positions, and infrastructure on interactive map layers.</p>
      </div>
    </div>
    <div style="text-align:center;margin-top:40px;">
      <a href="platform-overview.html" class="btn btn-outline">More Use Cases</a>
    </div>
  </div>
</section>

<!-- PLATFORM ECOSYSTEM DIAGRAM -->
<section class="ecosystem-section section">
  <div class="container">
    <div class="section-label">Platform Architecture</div>
    <h2 class="section-title" style="text-align:center;">The WellStream Platform Ecosystem</h2>
    <p class="section-desc" style="text-align:center;max-width:560px;margin:0 auto 48px;">Three interconnected data pillars that power end-to-end operations — from spud to abandonment.</p>
    <div class="ecosystem-diagram">
      <div class="eco-pillar">
        <span class="eco-icon">⛽</span>
        <h3>Well Data Lifecycle</h3>
        <p>Plan, drill, complete, and manage wells from spud to abandonment with full traceability.</p>
        <div class="eco-center-badge">Core</div>
      </div>
      <div class="eco-connector">
        <div class="eco-connector-line"></div>
      </div>
      <div class="eco-pillar">
        <span class="eco-icon">📈</span>
        <h3>Production Data Lifecycle</h3>
        <p>Capture, allocate, report, and optimize production volumes with automated pipelines.</p>
        <div class="eco-center-badge">Live</div>
      </div>
      <div class="eco-connector">
        <div class="eco-connector-line"></div>
      </div>
      <div class="eco-pillar">
        <span class="eco-icon">📋</span>
        <h3>Land Data Management</h3>
        <p>Track leases, agreements, obligations, and mineral rights across your entire portfolio.</p>
        <div class="eco-center-badge">Integrated</div>
      </div>
    </div>
  </div>
</section>

<!-- INDUSTRY TABS -->
<section class="industry-tabs-section section">
  <div class="container">
    <div class="section-label">Industries</div>
    <h2 class="section-title">Purpose-Built for Energy</h2>
    <div class="tabs-nav" role="tablist">
      <button class="tab-btn active" data-tab="ep" role="tab" aria-selected="true">E&amp;P</button>
      <button class="tab-btn" data-tab="midstream" role="tab">Midstream</button>
      <button class="tab-btn" data-tab="downstream" role="tab">Downstream</button>
      <button class="tab-btn" data-tab="utilities" role="tab">Utilities</button>
      <button class="tab-btn" data-tab="solar" role="tab">Solar/Wind</button>
      <button class="tab-btn" data-tab="mining" role="tab">Mining</button>
    </div>
    <div id="tab-ep" class="tab-pane active">
      <div class="tab-content-text">
        <h3>Exploration &amp; Production</h3>
        <p>WellStream's core platform was built for E&P operators. From well planning through abandonment, manage every data point in one unified system with real-time field sync.</p>
        <ul class="tab-feature-list">
          <li>Well data lifecycle management (WellView Allez)</li>
          <li>Real-time drilling data exchange (WellStream Innova)</li>
          <li>Frac stage tracking and pressure analysis</li>
          <li>Downtime analysis and reliability monitoring</li>
          <li>Mobile field data capture with offline sync</li>
        </ul>
        <a href="request-demo.html" class="btn btn-primary" style="margin-top:24px;">Request E&P Demo</a>
      </div>
      <div class="tab-visual">
        <div class="tab-metric"><span class="tab-metric-label">Active Wells</span><span class="tab-metric-value">2,847</span></div>
        <div class="tab-metric"><span class="tab-metric-label">Daily Production (BOE)</span><span class="tab-metric-value">142,650</span></div>
        <div class="tab-metric"><span class="tab-metric-label">Data Sync Latency</span><span class="tab-metric-value">&lt; 2 sec</span></div>
        <div class="tab-metric"><span class="tab-metric-label">Uptime SLA</span><span class="tab-metric-value">99.95%</span></div>
      </div>
    </div>
    <div id="tab-midstream" class="tab-pane">
      <div class="tab-content-text">
        <h3>Midstream Operations</h3>
        <p>Manage pipeline, gathering, and processing assets with integrated volume tracking, allocation management, and facility data oversight across your midstream portfolio.</p>
        <ul class="tab-feature-list">
          <li>Pipeline volume allocation and balancing</li>
          <li>Facility construction and commissioning tracking</li>
          <li>Compliance reporting automation</li>
          <li>Equipment tracking and maintenance logs</li>
          <li>Water management and disposal monitoring</li>
        </ul>
        <a href="request-demo.html" class="btn btn-primary" style="margin-top:24px;">Request Midstream Demo</a>
      </div>
      <div class="tab-visual">
