    setTimeout(function() {
      document.getElementById('cookieBanner').classList.add('visible');
    }, 1200);
  }
  function dismiss(val) {
    localStorage.setItem('ws_cookie_pref', val);
    document.getElementById('cookieBanner').style.transition = 'transform 0.3s ease';
    document.getElementById('cookieBanner').style.transform = 'translateY(100%)';
  }
  document.getElementById('cookieAccept').addEventListener('click', function() { dismiss('accepted'); });
  document.getElementById('cookieDecline').addEventListener('click', function() { dismiss('declined'); });
})();

