/* ===== WELLSTREAM SHARED STYLES ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #0D1B2A;
  --navy-mid: #1B2838;
  --navy-card: #111d2e;
  --navy-border: rgba(0,180,216,0.15);
  --blue: #00B4D8;
  --blue-dark: #0077B6;
  --green: #6CC24A;
  --gray-dark: #3C424B;
  --text-primary: #ffffff;
  --text-muted: rgba(255,255,255,0.55);
  --text-dim: rgba(255,255,255,0.35);
  --radius: 10px;
  --radius-lg: 16px;
  --shadow: 0 4px 24px rgba(0,0,0,0.3);
  --transition: 0.2s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  background: var(--navy);
  color: var(--text-primary);
  line-height: 1.6;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}

/* ===== LAYOUT ===== */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 96px 0;
}

/* ===== TYPOGRAPHY ===== */
.section-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--blue);
  margin-bottom: 16px;
}

.section-title {
  font-size: clamp(1.8rem, 4vw, 2.6rem);
  font-weight: 800;
  line-height: 1.15;
  color: var(--text-primary);
  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.section-desc {
  font-size: 1.05rem;
  color: var(--text-muted);
  line-height: 1.75;
  max-width: 620px;
  margin-bottom: 0;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 28px;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  border: 2px solid transparent;
  text-decoration: none;
  transition: all var(--transition);
  white-space: nowrap;
  letter-spacing: 0.01em;
}

.btn-primary {
  background: var(--blue);
  color: var(--navy);
  border-color: var(--blue);
}
.btn-primary:hover {
  background: #00c8f0;
  border-color: #00c8f0;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(0,180,216,0.35);
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border-color: rgba(255,255,255,0.25);
}
.btn-outline:hover {
  border-color: var(--blue);
  color: var(--blue);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--green);
  color: #0a1f0a;
  border-color: var(--green);
}
.btn-secondary:hover {
  background: #7de05a;
  border-color: #7de05a;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(108,194,74,0.35);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.82rem;
}

.btn-ghost {
  background: rgba(255,255,255,0.06);
  color: var(--text-primary);
  border-color: rgba(255,255,255,0.1);
}
.btn-ghost:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.2);
}

/* ===== NAVBAR ===== */
.navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 900;
  background: rgba(13,27,42,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,180,216,0.1);
  transition: background 0.3s;
}

.navbar.scrolled {
  background: rgba(13,27,42,0.98);
  border-bottom-color: rgba(0,180,216,0.2);
}

.nav-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 32px;
}

.nav-logo {
  font-size: 1.35rem;
  font-weight: 800;
  text-decoration: none;
  letter-spacing: -0.02em;
  flex-shrink: 0;
}
.logo-ws { color: #fff; }
.logo-stream { color: var(--blue); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.nav-link {
  background: none;
  border: none;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  padding: 8px 14px;
  cursor: pointer;
  text-decoration: none;
  border-radius: 6px;
  transition: color var(--transition), background var(--transition);
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-link:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.nav-link.active { color: var(--blue); }

.caret { font-size: 0.65em; transition: transform 0.2s; }
.nav-dropdown.open .caret { transform: rotate(180deg); }

.nav-dropdown {
  position: relative;
}

.dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-8px);
  background: #1a2840;
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: var(--radius-lg);
  padding: 8px;
  min-width: 260px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.nav-dropdown.open .dropdown-menu {
  opacity: 1;
  pointer-events: all;
  transform: translateX(-50%) translateY(0);
}

.dropdown-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--text-muted);
  transition: background var(--transition), color var(--transition);
}
.dropdown-item:hover {
  background: rgba(0,180,216,0.08);
  color: var(--text-primary);
}
.dropdown-item strong { display: block; color: var(--text-primary); font-size: 0.88rem; margin-bottom: 2px; }
.dropdown-item small { font-size: 0.76rem; color: var(--text-dim); }
.di-icon { font-size: 1.1rem; flex-shrink: 0; width: 32px; text-align: center; }

.nav-cta { margin-left: 16px; }

/* Mobile nav */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  margin-left: auto;
}
.nav-toggle span {
  display: block;
  width: 22px; height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

@media (max-width: 900px) {
  .nav-toggle { display: flex; }
  .nav-links {
    position: fixed;
    top: 72px; left: 0; right: 0;
    background: #0e1e30;
    border-bottom: 1px solid rgba(0,180,216,0.15);
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    margin: 0;
    padding: 16px;
    display: none;
    max-height: calc(100vh - 72px);
    overflow-y: auto;
  }
  .nav-links.open { display: flex; }
  .dropdown-menu {
    position: static;
    transform: none;
    opacity: 1;
    pointer-events: all;
    display: none;
    box-shadow: none;
    background: rgba(0,0,0,0.2);
    margin-top: 4px;
  }
  .nav-dropdown.open .dropdown-menu { display: block; }
  .nav-cta { margin: 16px; }
}

/* ===== PAGE HERO (inner pages) ===== */
.page-hero {
  padding: 160px 0 80px;
  background: linear-gradient(135deg, #0D1B2A 0%, #1B2838 60%, #0a1628 100%);
  position: relative;
  overflow: hidden;
}
.page-hero::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: radial-gradient(ellipse at 70% 40%, rgba(0,180,216,0.1) 0%, transparent 60%);
}
.page-hero-inner {
  position: relative;
  max-width: 700px;
}
.page-hero h1 {
  font-size: clamp(2rem, 4.5vw, 3.2rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: 20px;
  text-transform: uppercase;
}
.page-hero p {
  font-size: 1.1rem;
  color: var(--text-muted);
  line-height: 1.7;
}

/* ===== CARDS ===== */
.card {
  background: var(--navy-card);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px;
  transition: border-color var(--transition), transform var(--transition);
}
.card:hover {
  border-color: rgba(0,180,216,0.25);
  transform: translateY(-2px);
}

/* ===== FEATURE ICON ===== */
.feat-icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  margin-bottom: 18px;
  flex-shrink: 0;
}
.feat-icon.green {
  background: rgba(108,194,74,0.1);
  border-color: rgba(108,194,74,0.2);
}

/* ===== FOOTER ===== */
.footer {
  background: #080f18;
  border-top: 1px solid rgba(0,180,216,0.1);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .footer-tagline {
  font-size: 0.85rem;
  color: var(--text-dim);
  line-height: 1.6;
  margin-bottom: 20px;
}

.footer-login { display: flex; flex-direction: column; gap: 6px; margin-top: 16px; }
.footer-login-label { font-size: 0.75rem; font-weight: 600; color: var(--text-dim); text-transform: uppercase; letter-spacing: 1px; }
.footer-login-link {
  font-size: 0.82rem;
  color: var(--blue);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-login-link:hover { color: #00d4ff; }

.footer-col h4 {
  font-size: 0.82rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  font-size: 0.85rem;
  color: var(--text-dim);
  text-decoration: none;
  margin-bottom: 10px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.06);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-bottom p { font-size: 0.8rem; color: var(--text-dim); }
.footer-regions { display: flex; gap: 20px; }
.footer-regions span {
  font-size: 0.78rem;
  color: var(--text-dim);
  position: relative;
}
.footer-regions span:not(:last-child)::after {
  content: '·';
  margin-left: 20px;
  position: absolute;
}

@media (max-width: 960px) {
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 600px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 380px) {
  .footer-grid { grid-template-columns: 1fr; }
}

