  margin-bottom: 16px;
  letter-spacing: -0.02em;
}

.section-desc {
  font-size: 1.05rem;
  color: var(--text-muted);
  line-height: 1.75;
  max-width: 620px;
  margin-bottom: 0;
}

/* ===== BUTTONS ===== */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 13px 28px;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  border: 2px solid transparent;
  text-decoration: none;
  transition: all var(--transition);
  white-space: nowrap;
  letter-spacing: 0.01em;
}

.btn-primary {
  background: var(--blue);
  color: var(--navy);
  border-color: var(--blue);
}
.btn-primary:hover {
  background: #00c8f0;
  border-color: #00c8f0;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(0,180,216,0.35);
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border-color: rgba(255,255,255,0.25);
