.btn-outline:hover {
  border-color: var(--blue);
  color: var(--blue);
  transform: translateY(-1px);
}

.btn-secondary {
  background: var(--green);
  color: #0a1f0a;
  border-color: var(--green);
}
.btn-secondary:hover {
  background: #7de05a;
  border-color: #7de05a;
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(108,194,74,0.35);
}

.btn-sm {
  padding: 8px 18px;
  font-size: 0.82rem;
}

.btn-ghost {
  background: rgba(255,255,255,0.06);
  color: var(--text-primary);
  border-color: rgba(255,255,255,0.1);
}
.btn-ghost:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.2);
}

/* ===== NAVBAR ===== */
.navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 900;
  background: rgba(13,27,42,0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(0,180,216,0.1);
  transition: background 0.3s;
}

.navbar.scrolled {
  background: rgba(13,27,42,0.98);
  border-bottom-color: rgba(0,180,216,0.2);
}

.nav-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 32px;
}

.nav-logo {
  font-size: 1.35rem;
  font-weight: 800;
  text-decoration: none;
  letter-spacing: -0.02em;
  flex-shrink: 0;
}
.logo-ws { color: #fff; }
.logo-stream { color: var(--blue); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}

.nav-link {
  background: none;
  border: none;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  padding: 8px 14px;
  cursor: pointer;
  text-decoration: none;
  border-radius: 6px;
  transition: color var(--transition), background var(--transition);
  display: flex;
  align-items: center;
  gap: 4px;
}
.nav-link:hover { color: var(--text-primary); background: rgba(255,255,255,0.05); }
.nav-link.active { color: var(--blue); }

.caret { font-size: 0.65em; transition: transform 0.2s; }
.nav-dropdown.open .caret { transform: rotate(180deg); }

.nav-dropdown {
  position: relative;
}

.dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-8px);
  background: #1a2840;
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: var(--radius-lg);
  padding: 8px;
  min-width: 260px;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  box-shadow: 0 12px 40px rgba(0,0,0,0.4);
}
.nav-dropdown.open .dropdown-menu {
  opacity: 1;
  pointer-events: all;
  transform: translateX(-50%) translateY(0);
}

.dropdown-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 14px;
  border-radius: 8px;
  text-decoration: none;
  color: var(--text-muted);
  transition: background var(--transition), color var(--transition);
}
.dropdown-item:hover {
  background: rgba(0,180,216,0.08);
  color: var(--text-primary);
}
.dropdown-item strong { display: block; color: var(--text-primary); font-size: 0.88rem; margin-bottom: 2px; }
.dropdown-item small { font-size: 0.76rem; color: var(--text-dim); }
.di-icon { font-size: 1.1rem; flex-shrink: 0; width: 32px; text-align: center; }

.nav-cta { margin-left: 16px; }

/* Mobile nav */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  margin-left: auto;
}
.nav-toggle span {
  display: block;
  width: 22px; height: 2px;
  background: var(--text-primary);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

@media (max-width: 900px) {
  .nav-toggle { display: flex; }
  .nav-links {
    position: fixed;
    top: 72px; left: 0; right: 0;
    background: #0e1e30;
    border-bottom: 1px solid rgba(0,180,216,0.15);
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    margin: 0;
    padding: 16px;
