  transition: background 0.3s;
}

.navbar.scrolled {
  background: rgba(13,27,42,0.98);
  border-bottom-color: rgba(0,180,216,0.2);
}

.nav-inner {
  display: flex;
  align-items: center;
  height: 72px;
  gap: 32px;
}

.nav-logo {
  font-size: 1.35rem;
  font-weight: 800;
  text-decoration: none;
  letter-spacing: -0.02em;
  flex-shrink: 0;
}
.logo-ws { color: #fff; }
.logo-stream { color: var(--blue); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
