  border-radius: var(--radius-lg);
  padding: 28px;
  transition: border-color var(--transition), transform var(--transition);
}
.card:hover {
  border-color: rgba(0,180,216,0.25);
  transform: translateY(-2px);
}

/* ===== FEATURE ICON ===== */
.feat-icon {
  width: 48px; height: 48px;
  background: rgba(0,180,216,0.1);
  border: 1px solid rgba(0,180,216,0.2);
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 22px;
  margin-bottom: 18px;
  flex-shrink: 0;
}
.feat-icon.green {
  background: rgba(108,194,74,0.1);
  border-color: rgba(108,194,74,0.2);
}

/* ===== FOOTER ===== */
.footer {
  background: #080f18;
  border-top: 1px solid rgba(0,180,216,0.1);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 40px;
  margin-bottom: 48px;
}

.footer-brand .footer-tagline {
  font-size: 0.85rem;
  color: var(--text-dim);
  line-height: 1.6;
  margin-bottom: 20px;
}

.footer-login { display: flex; flex-direction: column; gap: 6px; margin-top: 16px; }
.footer-login-label { font-size: 0.75rem; font-weight: 600; color: var(--text-dim); text-transform: uppercase; letter-spacing: 1px; }
.footer-login-link {
  font-size: 0.82rem;
  color: var(--blue);
  text-decoration: none;
  transition: color var(--transition);
}
.footer-login-link:hover { color: #00d4ff; }

.footer-col h4 {
  font-size: 0.82rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-muted);
  margin-bottom: 16px;
}
.footer-col a {
  display: block;
  font-size: 0.85rem;
  color: var(--text-dim);
  text-decoration: none;
  margin-bottom: 10px;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.06);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  flex-wrap: wrap;
}
.footer-bottom p { font-size: 0.8rem; color: var(--text-dim); }
.footer-regions { display: flex; gap: 20px; }
.footer-regions span {
  font-size: 0.78rem;
  color: var(--text-dim);
  position: relative;
}
.footer-regions span:not(:last-child)::after {
  content: '·';
  margin-left: 20px;
  position: absolute;
}

@media (max-width: 960px) {
  .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
}
@media (max-width: 600px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 380px) {
  .footer-grid { grid-template-columns: 1fr; }
}

