[metadata] {"type": "create", "filePath": "/app/output/platform-overview.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Platform Overview — WellStream</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
<link rel="stylesheet" href="shared.css">
<style>
/* ===== PLATFORM OVERVIEW ===== */

/* Benefits */
.benefits-section { background: #111d2e; }
.benefits-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-top: 48px;
}
.benefit-card {
  background: var(--navy);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 32px 28px;
  transition: border-color 0.25s, transform 0.25s;
}
.benefit-card:hover { border-color: rgba(0,180,216,0.3); transform: translateY(-3px); }
.benefit-icon { font-size: 2rem; margin-bottom: 14px; display: block; }
.benefit-card h3 { font-size: 1.05rem; font-weight: 700; color: #fff; margin-bottom: 8px; }
.benefit-card p { font-size: 0.85rem; color: var(--text-muted); line-height: 1.7; }

/* Stats */
.stats-section { background: var(--navy); }
.stats-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  margin-top: 48px;
}
.stat-circle {
  text-align: center;
}
.stat-ring-wrap {
  position: relative;
  width: 160px;
  height: 160px;
  margin: 0 auto 20px;
}
.stat-ring-svg {
  width: 160px;
  height: 160px;
  transform: rotate(-90deg);
}
.stat-ring-bg { fill: none; stroke: rgba(255,255,255,0.06); stroke-width: 8; }
.stat-ring-fill { fill: none; stroke: var(--blue); stroke-width: 8; stroke-linecap: round; transition: stroke-dashoffset 1.2s cubic-bezier(0.4,0,0.2,1); }
.stat-ring-fill.green { stroke: var(--green); }
.stat-ring-fill.blue2 { stroke: #0077B6; }
.stat-inner {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.stat-num {
  font-size: 2.2rem;
  font-weight: 800;
  color: #fff;
  line-height: 1;
}
.stat-unit { font-size: 1rem; color: var(--blue); }
.stat-circle h4 { font-size: 0.95rem; font-weight: 600; color: #fff; margin-bottom: 6px; }
.stat-circle p { font-size: 0.82rem; color: var(--text-muted); line-height: 1.5; }

/* Implementation Timeline */
.timeline-section { background: #111d2e; }
.timeline-list { margin-top: 48px; display: flex; flex-direction: column; gap: 24px; }
.timeline-item {
  display: grid;
  grid-template-columns: 140px 1fr;
  gap: 24px;
  align-items: center;
  background: var(--navy);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px 32px;
}
.timeline-duration {
  text-align: center;
}
.timeline-duration .dur-val {
  font-size: 1.8rem;
  font-weight: 800;
  color: var(--blue);
  display: block;
  line-height: 1;
  margin-bottom: 4px;
}
.timeline-duration .dur-label {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: var(--text-dim);
}
.timeline-info h4 { font-size: 0.95rem; font-weight: 600; color: #fff; margin-bottom: 10px; }
.progress-bar-wrap {
  height: 6px;
  background: rgba(255,255,255,0.06);
  border-radius: 3px;
  overflow: hidden;
}
.progress-bar-fill {
  height: 100%;
  border-radius: 3px;
  background: linear-gradient(90deg, var(--blue), var(--green));
  transition: width 1.2s cubic-bezier(0.4,0,0.2,1);
}

/* Accordion */
.accordion-section { background: var(--navy); }
.accordion-wrap { margin-top: 48px; display: flex; flex-direction: column; gap: 0; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--radius-lg); overflow: hidden; }
.accordion-item { border-bottom: 1px solid rgba(255,255,255,0.06); }
.accordion-item:last-child { border-bottom: none; }
.accordion-header {
  width: 100%;
  background: none;
  border: none;
  font-family: inherit;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 24px 28px;
  cursor: pointer;
  text-align: left;
  transition: background 0.2s;
}
.accordion-header:hover { background: rgba(255,255,255,0.03); }
.accordion-header.open { background: rgba(0,180,216,0.05); }
.acc-icon {
  width: 40px; height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  background: rgba(0,180,216,0.08);
  border: 1px solid rgba(0,180,216,0.15);
  flex-shrink: 0;
  transition: background 0.2s, border-color 0.2s;
}
.accordion-header.open .acc-icon {
  background: rgba(0,180,216,0.15);
  border-color: rgba(0,180,216,0.4);
}
.acc-title { font-size: 1rem; font-weight: 600; color: #fff; flex: 1; }
.acc-chevron {
  width: 20px; height: 20px;
  flex-shrink: 0;
  color: var(--text-dim);
  transition: transform 0.3s, color 0.2s;
}
.accordion-header.open .acc-chevron { transform: rotate(180deg); color: var(--blue); }
.accordion-body {
  display: none;
  padding: 0 28px 28px 84px;
}
.accordion-body.open { display: block; }
.accordion-body p { font-size: 0.9rem; color: var(--text-muted); line-height: 1.75; }

/* Data Lifecycle Diagram */
.lifecycle-section { background: #111d2e; }
.lifecycle-diagram {
  margin-top: 48px;
  position: relative;
  overflow: hidden;
}
.lifecycle-phases {
  display: flex;
  gap: 0;
  border: 1px solid rgba(0,180,216,0.15);
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--navy);
}
.lifecycle-phase {
  flex: 1;
  padding: 28px 22px;
  text-align: center;
  border-right: 1px solid rgba(0,180,216,0.1);
  position: relative;
  transition: background 0.2s;
}
.lifecycle-phase:last-child { border-right: none; }
.lifecycle-phase:hover { background: rgba(0,180,216,0.04); }
.lifecycle-phase::after {
  content: '→';
  position: absolute;
  right: -14px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--blue);
  font-size: 1.2rem;
  z-index: 2;
}
.lifecycle-phase:last-child::after { display: none; }
.lp-num {
  font-size: 1.8rem;
  font-weight: 800;
  color: rgba(0,180,216,0.25);
  display: block;
  margin-bottom: 8px;
}
.lp-title { font-size: 0.82rem; font-weight: 700; color: #fff; margin-bottom: 6px; }
.lp-sub { font-size: 0.72rem; color: var(--text-dim); line-height: 1.5; }
.lifecycle-rows {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-top: 32px;
}
.lifecycle-row {
  background: var(--navy);
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius);
  padding: 20px 24px;
  display: flex;
  align-items: center;
  gap: 16px;
}
.lr-badge {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 1px;
  padding: 4px 10px;
  border-radius: 20px;
  white-space: nowrap;
  flex-shrink: 0;
}
.lr-badge.blue { background: rgba(0,180,216,0.15); color: var(--blue); }
.lr-badge.green { background: rgba(108,194,74,0.15); color: var(--green); }
.lr-badge.navy { background: rgba(21,41,90,0.6); color: rgba(255,255,255,0.55); border: 1px solid rgba(255,255,255,0.1); }
.lr-text { font-size: 0.85rem; color: var(--text-muted); line-height: 1.5; flex: 1; }

/* Testimonials */
.testimonials-section { background: var(--navy); }
.testimonials-carousel {
  margin-top: 48px;
  position: relative;
}
.testimonials-track {
  overflow: hidden;
}
.testimonials-inner {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4,0,0.2,1);
}
.testimonial-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}
.testimonial-card {
  background: #111d2e;
  border: 1px solid rgba(255,255,255,0.06);
  border-radius: var(--radius-lg);
  padding: 28px;
}
.testimonial-card blockquote {
  font-size: 0.95rem;
  color: rgba(255,255,255,0.7);
  line-height: 1.7;
  margin-bottom: 20px;
  position: relative;
  padding-left: 16px;
}
.testimonial-card blockquote::before {
  content: '';
  position: absolute;
  left: 0; top: 4px; bottom: 4px;
  width: 3px;
  background: var(--blue);
  border-radius: 2px;
}
.testimonial-meta { font-size: 0.8rem; color: var(--text-dim); font-style: italic; }
.testimonial-stars { color: #FFC107; font-size: 0.85rem; margin-bottom: 12px; letter-spacing: 2px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 28px;
}
.carousel-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.2);
  border: none;
  cursor: pointer;
