<script>
// Form validation and submission
document.getElementById('demoForm').addEventListener('submit', function(e) {
  e.preventDefault();
  var valid = true;

  // Clear previous errors
  document.querySelectorAll('.form-input, .form-select').forEach(function(el) {
    el.classList.remove('error');
  });

  // Validate required fields
  var required = ['firstName', 'lastName', 'email', 'company', 'jobTitle', 'country'];
  required.forEach(function(id) {
    var el = document.getElementById(id);
    if (!el.value.trim()) {
      el.classList.add('error');
      valid = false;
    }
  });

  // Email validation
  var emailEl = document.getElementById('email');
  var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (emailEl.value && !emailPattern.test(emailEl.value)) {
    emailEl.classList.add('error');
    valid = false;
  }

  if (!valid) return;

  // Simulate submission
  var btn = document.getElementById('formSubmit');
  btn.disabled = true;
  btn.textContent = 'Submitting...';

  setTimeout(function() {
    document.getElementById('demoForm').style.display = 'none';
    document.getElementById('formSuccess').classList.add('visible');
    document.querySelector('.demo-form-title').textContent = 'Thank You!';
  }, 1000);
});

// Remove error state on input
document.querySelectorAll('.form-input, .form-select').forEach(function(el) {
  el.addEventListener('input', function() {
    this.classList.remove('error');
  });
});
</script>
